filepath.WalkDir(directory, func(path string, entry os.DirEntry, err error) error {
	if err != nil {

		if entry != nil && entry.IsDir() {
			return filepath.SkipDir
		}
		return err
	}
	relative, err := filepath.Rel(directory, path)
	if err != nil {
		return err
	}
	information, err := entry.Info()
	if err != nil {
		return err
	}
	if entry.IsDir() {
		found[relative] = fmt.Sprintf("directory %v", information.Mode().Perm())
		return nil
	}
	contents, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	found[relative] = fmt.Sprintf("file %v %q", information.Mode().Perm(), contents)
	return nil
})

filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
	if err != nil {
		if entry != nil && entry.IsDir() {
			return filepath.SkipDir
		}
		return err
	}
	relative, err := filepath.Rel(root, path)
	if err != nil {
		return err
	}
	info, err := entry.Info()
	if err != nil {
		return err
	}
	if entry.Type()&os.ModeSymlink != 0 {
		target, err := os.Readlink(path)
		if err != nil {
			return err
		}
		result[relative] = "link " + target
		return nil
	}
	if entry.IsDir() {
		result[relative] = fmt.Sprintf("directory %v", info.Mode().Perm())
		return nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	result[relative] = fmt.Sprintf("file %v %q", info.Mode().Perm(), data)
	return nil
})
